-style:normal;color:var(--orange)}.intro{color:#d4d0c0;font-size:18px;letter-spacing:.3px;margin:0 0 32px}.primary-button{background:var(--orange);border:0;padding:16px 21px;min-width:220px;text-align:left;font-size:13px;font-weight:800;letter-spacing:1.2px;cursor:pointer;clip-path:polygon(0 0,100% 0,100% 75%,94% 100%,0 100%);transition:background .15s,transform .15s}.primary-button:hover{background:#e7834e;transform:translateY(-2px)}.primary-button span{float:right}.title-foot{font:9px 'DM Mono';letter-spacing:1px;color:#848b7e;margin-top:25px}.title-aside{position:absolute;right:11vw;top:35%;width:180px;color:var(--lime);font:10px 'DM Mono';letter-spacing:2px}.title-aside>div{height:1px;background:var(--line);margin:14px 0}.title-aside small{font-size:9px;line-height:2;color:#b1b19f}.title-hint{position:absolute;bottom:40px;left:10.5vw;color:#a6aa9d;font:10px 'DM Mono';letter-spacing:.2px}.title-hint b{color:var(--orange);padding:0 8px}#hud{position:absolute;inset:0;z-index:3;pointer-events:none}.mission-card,.survivor-card,.weapon-card{position:absolute;background:linear-gradient(135deg,rgba(11,17,15,.88),rgba(17,24,21,.7));border:1px solid var(--line);clip-path:polygon(0 0,100% 0,100% calc(100% - 11px),calc(100% - 11px) 100%,0 100%)}.mission-card{top:78px;left:34px;width:234px;padding:14px 16px}.mission-card strong{display:block;font-size:17px;letter-spacing:1px;margin:5px 0 1px}.mission-card small{display:block;color:#9da398;font:9px 'DM Mono';letter-spacing:.3px}.objective-progress{height:2px;background:#434b40;margin:12px 0 7px}.objective-progress span{display:block;width:0;height:100%;background:var(--orange);transition:width .25s}.mission-card #progress-text{color:#d4c9a8}.survivor-card{top:78px;right:34px;width:220px;padding:13px 15px}.survivor-top{display:flex;align-items:center;gap:9px}.portrait{width:31px;height:32px;background:linear-gradient(140deg,#9c5836,#332b25);display:grid;place-items:center;font-size:19px;font-weight:800;color:#e3c28f;border:1px solid #d28551}.survivor-top .micro-label{font-size:8px;display:block;letter-spacing:1px}.survivor-top b{font:9px 'DM Mono';color:var(--lime)}.status-dot{width:6px;height:6px;border-radius:50%;background:#a7bc6c;margin-left:auto;box-shadow:0 0 9px #a7bc6c}.health-row,.stamina-row{display:flex;align-items:center;gap:8px;margin-top:11px;font:8px 'DM Mono';color:#b4b5a8}.health-row b{font:11px 'DM Mono';color:var(--ink);width:22px;text-align:right}.health-track,.stamina-track{height:5px;flex:1;background:#42443b;transform:skewX(-18deg)}.health-track i,.stamina-track i{height:100%;display:block;background:var(--orange);width:100%;transition:width .2s}.stamina-row{margin-top:7px}.stamina-track{height:3px}.stamina-track i{background:var(--lime)}.weapon-card{right:34px;bottom:60px;width:218px;padding:12px 15px}.weapon-name{display:flex;align-items:baseline;gap:8px}.weapon-name .micro-label{font-size:8px}.weapon-name b{font-size:13px;letter-spacing:.8px}.weapon-name #weapon-slot{font:9px 'DM Mono';color:#93998c;margin-left:auto}.ammo{display:flex;align-items:baseline;margin-top:1px}.ammo strong{font:39px 'Barlow Condensed';line-height:1;color:#e7dfc8}.ammo>span{font:17px 'DM Mono';color:#77796c;margin:0 5px}.ammo>b{font:17px 'DM Mono';color:#adb19c}.ammo small{font:8px 'DM Mono';letter-spacing:1.5px;color:#989b8b;margin-left:auto}.weapon-switch{margin-top:6px;border-top:1px solid var(--line);padding-top:7px;color:#a4a89a;font:8px 'DM Mono';letter-spacing:.6px}.weapon-switch span{color:var(--orange)}.weapon-switch i{display:inline-block;width:1px;height:9px;background:var(--line);margin:0 8px -1px}.bottomline{z-index:4;position:absolute;bottom:0;left:0;right:0;height:36px;background:rgba(10,14,13,.83);border-top:1px solid var(--line);display:flex;align-items:center;padding:0 34px;gap:22px;color:#d0ccba;font:9px 'DM Mono';letter-spacing:.5px;pointer-events:none}.bottomline small{color:#858c80;font-size:8px;margin-left:4px}.footer-right{margin-left:auto;color:var(--orange);letter-spacing:1.3px}.crosshair{position:absolute;left:50%;top:50%;width:25px;height:25px;transform:translate(-50%,-50%);opacity:.9}.crosshair i,.crosshair b{position:absolute;background:#e8dfc7;box-shadow:0 0 3px #111}.crosshair i{width:1px;height:5px;left:12px;top:0;box-shadow:0 20px 3px #111}.crosshair b{height:1px;width:5px;top:12px;left:0;box-shadow:20px 0 3px #111}.crosshair::after{content:'';position:absolute;width:3px;height:3px;border:1px solid var(--orange);border-radius:50%;left:10px;top:10px}.interact-hint,.toast{position:absolute;left:50%;transform:translateX(-50%);bottom:76px;background:rgba(10,15,13,.86);border:1px solid var(--line);padding:9px 16px;color:#e9dfc8;font:10px 'DM Mono';letter-spacing:1px}.toast{bottom:125px;color:var(--lime);opacity:0;transition:opacity .2s}.toast.show{opacity:1}.inventory{position:absolute;inset:0;display:grid;place-items:center;background:rgba(5,9,8,.73);pointer-events:auto}.inventory-panel{width:min(600px,90vw);background:#151c18;border:1px solid rgba(220,218,191,.35);padding:23px 27px;box-shadow:0 18px 80px #000}.inventory-heading{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:15px}.inventory-heading h2{font-size:32px;letter-spacing:2px;margin:3px 0 0}.inventory-heading button{background:none;border:0;color:#a8aa9c;font-size:30px;cursor:pointer}.inventory-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.item{min-height:115px;padding:12px;text-align:left;background:#1c2520;border:1px solid var(--line);display:flex;flex-direction:column;align-items:flex-start;color:var(--ink)}.item.selected{border-color:var(--orange)}.item-icon{color:var(--orange);font-size:23px;line-height:1.1}.item strong{font-size:13px;letter-spacing:1px;margin-top:5px}.item small{font:9px 'DM Mono';color:#9ba194;margin-top:2px}.item>b{font:9px 'DM Mono';color:var(--lime);margin-top:auto;padding-top:8px}.inventory-note{font:9px 'DM Mono';color:#a1a696;margin-bottom:0;margin-top:17px}kbd{border:1px solid #64685a;padding:2px 5px;color:var(--ink)}.damage-flash{position:absolute;inset:0;background:rgba(157,27,19,.35);opacity:0;transition:opacity .2s}.damage-flash.hit{opacity:1}.end-card{max-width:490px}.end-card h2{font-size:70px;line-height:.84;letter-spacing:-2px;margin:22px 0}.end-card p{color:#c3c4b5;font-size:16px;max-width:350px}.end-stats{display:flex;gap:35px;margin:27px 0}.end-stats span{font:9px 'DM Mono';color:#979c8e;letter-spacing:.5px}.end-stats b{display:block;font:22px 'Barlow Condensed';color:var(--lime);margin-top:6px}.mobile-controls{display:none}.mobile-actions{display:none}
