@media(max-height:560px) and (min-width:701px){.title-copy h1{font-size:90px}.title-copy{margin-top:12px}.mission-card,.survivor-card{top:55px}.weapon-card{bottom:45px}}

(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d',{alpha:false});
const $=s=>document.querySelector(s),ui={title:$('#title-screen'),hud:$('#hud'),end:$('#end-screen'),inventory:$('#inventory'),health:$('#health-fill'),healthVal:$('#health-value'),stamina:$('#stamina-fill'),mag:$('#ammo-mag'),reserve:$('#ammo-reserve'),weapon:$('#weapon-name'),slot:$('#weapon-slot'),objective:$('#objective'),sub:$('#objective-sub'),progress:$('#progress-fill'),progressText:$('#progress-text'),hint:$('#interact-hint'),toast:$('#toast'),damage:$('#damage-flash'),cross:$('#crosshair')};
let W=0,H=0,dpr=1, running=false,paused=false, last=0, elapsed=0, toastTimer=0, fireTimer=0, hurtTimer=0, spawnTimer=0;
const game={x:0,z:0,y:0,yaw:0,health:100,stamina:100,kills:0,herbs:1,weapon:0,ammo:[12,4],reserve:[48,16],reloading:false,reloadTimer:0,jump:0,jumpV:0,invuln:0,walk:0,flash:0};
const weapons=[{name:'PISTOLA 9MM',capacity:12,damage:38,rate:.32,reload:1.15,range:20},{name:'ESCOPETA',capacity:4,damage:74,rate:.72,reload:1.65,range:12}];
let zombies=[], pickups=[], polygons=[], staticPolys=[], scenery=[], keys=new Set(), cursor={x:0,y:0}, camera={x:0,y:0,z:0,fx:0,fy:0,fz:-1,rx:1,ry:0,rz:0,ux:0,uy:1,uz:0}, shake=0,gameEnd=false;
const rnd=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b,c,d)=>Math.hypot(a-c,b-d);
function resize(){dpr=Math.min(devicePixelRatio||1,1.35);W=innerWidth;H=innerHeight;canvas.width=Math.round(W*dpr*.72);canvas.height=Math.round(H*dpr*.72);ctx.setTransform(1,0,0,1,0,0);ctx.imageSmoothingEnabled=false;}
addEventListener('resize',resize);resize();
function vec(x,y,z){return{x,y,z}}
function rotPoint(p,yaw){const c=Math.cos(yaw),s=Math.sin(yaw);return{x:p.x*c+p.z*s,y:p.y,z:-p.x*s+p.z*c}}
function project(p){let x=p.x-camera.x,y=p.y-camera.y,z=p.z-camera.z;const cx=x*camera.rx+y*camera.ry+z*camera.rz,cy=x*camera.ux+y*camera.uy+z*camera.uz,cz=x*camera.fx+y*camera.fy+z*camera.fz;if(cz<.1)return null;const f=canvas.height*.83;return{x:canvas.width/2+cx*f/cz,y:canvas.height*.53-cy*f/cz,d:cz}}
function addPoly(points,color,depth=null){const ps=points.map(project);if(ps.some(p=>!p))return;const d=depth??ps.reduce((a,p)=>a+p.d,0)/ps.length;polygons.push({ps,color,d})}
function boxFaces(cx,cy,cz,sx,sy,sz,color,yaw=0){const hx=sx/2,hy=sy/2,hz=sz/2;const pts=[[-hx,-hy,-hz],[hx,-hy,-hz],[hx,hy,-hz],[-hx,hy,-hz],[-hx,-hy,hz],[hx,-hy,hz],[hx,hy,hz],[-hx,hy,hz]].map(([x,y,z])=>{const r=rotPoint({x,y,z},yaw);return{x:cx+r.x,y:cy+r.y,z:cz+r.z}});const faces=[[0,1,2,3],[5,4,7,6],[4,0,3,7],[1,5,6,2],[3,2,6,7],[4,5,1,0]],shades=Array.isArray(color)?color:[color];faces.forEach((face,i)=>addPoly(face.map(j=>pts[j]),shades[i%shades.length]));}
function quad(x1,z1,x2,z2,y,color){addPoly([vec(x1,y,z1),vec(x2,y,z1),vec(x2,y,z2),vec(x1,y,z2)],color)}
function cyl(x,y,z,r,h,color,sides=7,yaw=0){const top=[],bottom=[];for(let i=0;i<sides;i++){const a=i/sides*Math.PI*2+yaw;top.push(vec(x+Math.cos(a)*r,y+h,z+Math.sin(a)*r));bottom.push(vec(x+Math.cos(a)*r,y,z+Math.sin(a)*r))}for(let i=0;i<sides;i++){const j=(i+1)%sides;addPoly([bottom[i],bottom[j],top[j],top[i]],i%2?'#55554a':color)}addPoly(top,color)}
function sphereMesh(x,y,z,sx,sy,sz,color,yaw=0){const rings=[[0,1],[-.65,.76],[.65,.76],[-1,0],[1,0]],pts=rings.map(([yy,r])=>Array.from({length:7},(_,i)=>{const a=i/7*Math.PI*2;const p=rotPoint({x:Math.cos(a)*sx*r,y:yy*sy,z:Math.sin(a)*sz*r},yaw);return vec(x+p.x,y+p.y,z+p.z)}));for(let i=0;i<7;i++){const j=(i+1)%7;addPoly([pts[0][i],pts[0][j],pts[1][j],pts[1][i]],color);addPoly([pts[0][i],pts[2][i],pts[2][j],pts[0][j]],color);addPoly([pts[1][i],pts[1][j],pts[3][0],pts[3][0]],color);addPoly([pts[2][i],pts[4][0],pts[2][j]],color)}}
function buildStatic(){staticPolys=[];polygons=[];
// street, sidewalks, sandy shoulder
quad(-28,15,28,-95,0,'#4a4941');quad(-5,15,-28,-95,.05,'#777466');quad(5,15,28,-95,.05,'#777466');quad(-3.6,15,3.6,-95,.09,'#484941');
// broken curb / road markings
for(let z=-3;z>-90;z-=8)quad(-.09,z,.09,z-3,.12,'#b4a779');
for(let side of [-1,1]){
  // curb strip and sidewalks
  quad(side*3.55,15,side*3.9,-95,.16,'#a49a7e');
  for(let z=12;z>-93;z-=10){
    const bx=side*rnd(7.5,10.5),bz=z+rnd(-3,3),bw=rnd(5.5,8),bd=rnd(8,12),bh=rnd(4.5,8);
    const wall=['#827667','#77786b','#8b7865','#6d7167','#9a826c'][Math.floor(rnd(0,5))];
    boxFaces(bx,bh/2,bz,bw,bh,bd,[wall,'#554f47','#71685a','#615c52','#a2957c','#6a6053']);
    boxFaces(bx,bh+.12,bz,bw+.3,.24,bd+.3,'#554d43');
    // windows and chipped shutters facing road
    const faceX=bx-side*(bw/2+.03);for(let wy=1.5;wy<bh-1;wy+=2.2){for(let zz=bz-bd*.3;zz<bz+bd*.38;zz+=2.7){boxFaces(faceX,wy,zz,.07,1.05,1.25,Math.random()>.3?'#293638':'#3e3931');boxFaces(faceX-side*.05,wy,zz,.08,.08,1.35,'#987b54');}}
    // street-facing awning
    if(Math.random()>.42){boxFaces(bx-side*(bw/2+.65),2.6,bz-bd*.12,1.25,.12,Math.min(3,bd*.55),Math.random()>.5?'#9c4932':'#77784d');}
    scenery.push({type:'sign',x:bx-side*(bw/2+.12),y:bh*.72,z:bz,side});
  }
  // palms, utility poles and wrecks
  for(let z=11;z>-91;z-=rnd(8,13)){
    const x=side*rnd(4.5,6.1),height=rnd(5,8);scenery.push({type:'palm',x,y:0,z,h:height});
    if(Math.random()>.55)scenery.push({type:'pole',x:side*rnd(4.3,5.3),y:0,z:z-rnd(3,5),h:rnd(4.5,6)});
  }
}
// scattered wrecks and bins
for(let i=0;i<8;i++){const z=rnd(-80,10),x=rnd(-2.8,2.8);boxFaces(x,.55,z,1.5,.9,2.2,'#393b36',rnd(-.2,.2));boxFaces(x,.96,z,1.52,.08,2.18,'#55584d')}
for(let i=0;i<80;i++){const x=rnd(-4,4),z=rnd(-95,15),size=rnd(.04,.18);quad(x,z,x+size,z-size,.14,Math.random()>.5?'#817a66':'#343b36')}
staticPolys=polygons;polygons=[];
}
buildStatic();
function cameraUpdate(){const yaw=game.yaw;const bx=Math.sin(yaw),bz=Math.cos(yaw);camera.x=game.x+bx*6.6;camera.y=3.35;camera.z=game.z+bz*6.6;const tx=game.x-bx*2.2,ty=1.25,tz=game.z-bz*3.4;let fx=tx-camera.x,fy=ty-camera.y,fz=tz-camera.z,l=Math.hypot(fx,fy,fz);camera.fx=fx/l;camera.fy=fy/l;camera.fz=fz/l;camera.rx=-camera.fz;camera.ry=0;camera.rz=camera.fx;l=Math.hypot(camera.rx,camera.rz);camera.rx/=l;camera.rz/=l;camera.ux=camera.ry*camera.fz-camera.rz*camera.fy;camera.uy=camera.rz*camera.fx-camera.rx*camera.fz;camera.uz=camera.rx*camera.fy-camera.ry*camera.fx}

