function projectVisible(points){let verts=points.map(p=>{const x=p.x-camera.x,y=p.y-camera.y,z=p.z-camera.z;return{x:x*camera.rx+y*camera.ry+z*camera.rz,y:x*camera.ux+y*camera.uy+z*camera.uz,d:x*camera.fx+y*camera.fy+z*camera.fz}});const near=.12,clipped=[];for(let i=0;i<verts.length;i++){const a=verts[i],b=verts[(i+1)%verts.length],ina=a.d>near,inb=b.d>near;if(ina)clipped.push(a);if(ina!==inb){const t=(near-a.d)/(b.d-a.d);clipped.push({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,d:near})}}if(clipped.length<3)return null;const f=canvas.height*.83;return clipped.map(p=>({x:canvas.width/2+p.x*f/p.d,y:canvas.height*.53-p.y*f/p.d,d:p.d}))}
