function updateHud(){ui.health.style.width=game.health+'%';ui.healthVal.textContent=Math.ceil(game.health);ui.stamina.style.width=game.stamina+'%';ui.mag.textContent=game.ammo[game.weapon];ui.reserve.textContent=game.reserve[game.weapon];ui.weapon.textContent=weapons[game.weapon].name;ui.slot.textContent=`0${game.weapon+1} / 02`;$('#inv-pistol').textContent=`${game.ammo[0]} / ${game.reserve[0]}`;$('#inv-shotgun').textContent=`${game.ammo[1]} / ${game.reserve[1]}`;$('#inv-herbs').textContent=`${game.herbs} unidade${game.herbs===1?'':'s'}`;const done=Math.min(game.kills,8);ui.progress.style.width=(done/8*100)+'%';ui.progressText.textContent=`AMEAÇAS ${done} / 8`;if(done>=8){ui.objective.textContent='ALCANCE O FAROL';ui.sub.textContent='Siga a luz no fim da avenida'}else{ui.objective.textContent='ENCONTRE O FAROL';ui.sub.textContent='Elimine as ameaças no caminho'}const close=pickups.find(p=>dist(p.x,p.z,game.x,game.z)<1.65);ui.hint.classList.toggle('hidden',!close||paused);if(close)ui.hint.textContent=close.type==='ammo'?'[ E ] PEGAR MUNIÇÃO':'[ E ] PEGAR ERVA MEDICINAL';ui.cross.style.left=`${cursor.x}px`;ui.cross.style.top=`${cursor.y}px`}
function showToast(message){ui.toast.textContent=message;ui.toast.classList.add('show');toastTimer=2.2}
